(7456073, 1181512, 76335, '<td valign="top">Like windblown chalk. Nice.</td>', 'Like windblown chalk. Nice.', '2016-05-23 01:03:22.000000', NULL, 1),
(7456076, 1181679, 76335, '<td valign="top">The title seems heavy -- or makes me think I''m missing something. I do like the point of view here which makes the leaf feel like an airfield.</td>', 'The title seems heavy -- or makes me think I''m missing something. I do like the point of view here which makes the leaf feel like an airfield.', '2016-05-23 01:06:11.000000', NULL, 1),
(7456077, 1181614, 76335, '<td valign="top">Nailed it. Thank you.</td>', 'Nailed it. Thank you.', '2016-05-23 01:06:53.000000', NULL, 1),
(7456078, 1181618, 76335, '<td valign="top">Dark yet fun. Good stuff.</td>', 'Dark yet fun. Good stuff.', '2016-05-23 01:07:20.000000', NULL, 1),
(7456079, 1181338, 76335, '<td valign="top">A culinary visual abstract delight.</td>', 'A culinary visual abstract delight.', '2016-05-23 01:07:54.000000', NULL, 1),
(7456081, 1181662, 76335, '<td valign="top">The backlighting carves out the shapes nicely.</td>', 'The backlighting carves out the shapes nicely.', '2016-05-23 01:08:38.000000', NULL, 1),
(7456082, 1181575, 76335, '<td valign="top">Lots of coming and going here. And a double bike with five wheels. And a three legged two-thrids man. Fun.</td>', 'Lots of coming and going here. And a double bike with five wheels. And a three legged two-thrids man. Fun.', '2016-05-23 01:09:33.000000', NULL, 1),
(7456084, 1181463, 76335, '<td valign="top">Disturbingly excellent.</td>', 'Disturbingly excellent.', '2016-05-23 01:09:56.000000', NULL, 1),
(7456085, 1181601, 76335, '<td valign="top">A cliché scene, but so irresistible. Giving it an eight against my art snobbery.</td>', 'A cliché scene, but so irresistible. Giving it an eight against my art snobbery.', '2016-05-23 01:10:58.000000', NULL, 1),
(7456087, 1181606, 76335, '<td valign="top">Ha! Well seen and nicely framed. Love the humor.</td>', 'Ha! Well seen and nicely framed. Love the humor.', '2016-05-23 01:11:39.000000', NULL, 1),
(7456088, 1181502, 76335, '<td valign="top">And me too. A gritty sort of shadow puppet show. I like it.</td>', 'And me too. A gritty sort of shadow puppet show. I like it.', '2016-05-23 01:12:17.000000', NULL, 1),
(7456089, 1181398, 76335, '<td valign="top">Men at work. I do like the tableau.</td>', 'Men at work. I do like the tableau.', '2016-05-23 01:12:58.000000', NULL, 1),
(7456090, 1181408, 76335, '<td valign="top">Beautiful really.</td>', 'Beautiful really.', '2016-05-23 01:13:08.000000', NULL, 1),
(7456093, 1181697, 76335, '<td valign="top">Wow! Dark windows to a past time, another world. I look forward to hearing more.</td>', 'Wow! Dark windows to a past time, another world. I look forward to hearing more.', '2016-05-23 01:14:07.000000', NULL, 1),
(7456094, 1181658, 76335, '<td valign="top">Nicely done, but the little bit of color is superb. Icing on the cake.</td>', 'Nicely done, but the little bit of color is superb. Icing on the cake.', '2016-05-23 01:15:58.000000', NULL, 1),
(7456095, 1181694, 76335, '<td valign="top">Impressive if legal.</td>', 'Impressive if legal.', '2016-05-23 01:16:28.000000', NULL, 1),
(7456098, 1181641, 76335, '<td valign="top">Poetic.</td>', 'Poetic.', '2016-05-23 01:17:37.000000', NULL, 1),
(7456099, 1181659, 76335, '<td valign="top">Love this.</td>', 'Love this.', '2016-05-23 01:19:01.000000', NULL, 1),
(7456101, 1181544, 76335, '<td valign="top">Funky. Great title.</td>', 'Funky. Great title.', '2016-05-23 01:20:25.000000', NULL, 1),
(7456102, 1181464, 76335, '<td valign="top">Too bizarre to hate.</td>', 'Too bizarre to hate.', '2016-05-23 01:20:52.000000', NULL, 1),
(7456104, 1181373, 76335, '<td valign="top">Earthy and packs a punch.</td>', 'Earthy and packs a punch.', '2016-05-23 01:22:11.000000', NULL, 1),
(7456128, 1181601, 66616, '<td valign="top">Nice work the light is very nice.</td>', 'Nice work the light is very nice.', '2016-05-23 04:38:41.000000', NULL, 1),
(7456145, 1181544, 52854, '<td valign="top">Cool photo - Interesting -</td>', 'Cool photo - Interesting -', '2016-05-23 09:03:38.000000', NULL, 1),
(7456148, 1181572, 52854, '<td valign="top">Great shot - Nice contrast. Love the eyes.</td>', 'Great shot - Nice contrast. Love the eyes.', '2016-05-23 09:11:35.000000', NULL, 1),
(7456162, 1181682, 38032, '<td valign="top">in my top 3 in this one. Nice tones and textures.</td>', 'in my top 3 in this one. Nice tones and textures.', '2016-05-23 11:01:12.000000', NULL, 1),
(7456163, 1181579, 38032, '<td valign="top">nice composition.</td>', 'nice composition.', '2016-05-23 11:01:59.000000', NULL, 1),
(7456165, 1181544, 16148, '<td valign="top">I like the implied movement as she exits the frame.  Terrific!</td>', 'I like the implied movement as she exits the frame.  Terrific!', '2016-05-23 11:27:09.000000', NULL, 1),
(7456166, 1181662, 16148, '<td valign="top">Beautiful high contrast image.</td>', 'Beautiful high contrast image.', '2016-05-23 11:27:47.000000', NULL, 1),
(7456167, 1181610, 16148, '<td valign="top">Brilliant exposure!  My favorite in the challenge.</td>', 'Brilliant exposure!  My favorite in the challenge.', '2016-05-23 11:30:02.000000', NULL, 1),
(7456168, 1181613, 16148, '<td valign="top">Beautifully done.  You managed to stay out of the way, allowing the light to dance.</td>', 'Beautifully done.  You managed to stay out of the way, allowing the light to dance.', '2016-05-23 11:31:20.000000', NULL, 1),
(7456169, 1181497, 16148, '<td valign="top">Through the aperture.  Very nicely done!</td>', 'Through the aperture.  Very nicely done!', '2016-05-23 11:31:54.000000', NULL, 1),
(7456170, 1181606, 16148, '<td valign="top">Thought provoking and your title opens the door.</td>', 'Thought provoking and your title opens the door.', '2016-05-23 11:34:03.000000', NULL, 1),
(7456172, 1181659, 16148, '<td valign="top">No processing needed.  Terrific feeling straight from the camera.  Very enjoyable.</td>', 'No processing needed.  Terrific feeling straight from the camera.  Very enjoyable.', '2016-05-23 11:35:16.000000', NULL, 1),
(7456176, 1181628, 16148, '<td valign="top">Hold on!  Destination unknown.  Great!</td>', 'Hold on!  Destination unknown.  Great!', '2016-05-23 11:38:25.000000', NULL, 1),
(7456196, 1181491, 52854, '<td valign="top">sweet family photo :)</td>', 'sweet family photo :)', '2016-05-23 13:51:15.000000', NULL, 1),
(7456198, 1181544, 30982, '<td valign="top">Lovely jumble of visual elements - great job with exposure, too!</td>', 'Lovely jumble of visual elements - great job with exposure, too!', '2016-05-23 14:19:08.000000', NULL, 1),
(7456199, 1181512, 30982, '<td valign="top">Like a pointillist dream.  (I have no idea of that''s a word but I like it anyway.)  Also really like the use of the square exposure.  I''d never think of setting a camera for that.  I do shoot that way on the phone sometimes.</td>', 'Like a pointillist dream.  (I have no idea of that''s a word but I like it anyway.)  Also really like the use of the square exposure.  I''d never think of setting a camera for that.  I do shoot that way on the phone sometimes.', '2016-05-23 14:20:12.000000', NULL, 1),
(7456200, 1181641, 30982, '<td valign="top">Interesting to blur just the face - nicely done with minimal, too.</td>', 'Interesting to blur just the face - nicely done with minimal, too.', '2016-05-23 14:20:52.000000', NULL, 1),
(7456201, 1181504, 30982, '<td valign="top">A nice still life, well lit and composed.</td>', 'A nice still life, well lit and composed.', '2016-05-23 14:21:04.000000', NULL, 1),
(7456202, 1181491, 30982, '<td valign="top">I''ll just go with "awwww!"  This is really quite nice.  I like that the dogs are the only ones actually paying attention.  I''m going to wager the folks in the picture are well-pleased with the result.  Very sweet.</td>', 'I''ll just go with "awwww!"  This is really quite nice.  I like that the dogs are the only ones actually paying attention.  I''m going to wager the folks in the picture are well-pleased with the result.  Very sweet.', '2016-05-23 14:21:49.000000', NULL, 1),
(7456203, 1181408, 30982, '<td valign="top">Nice catch of the light!</td>', 'Nice catch of the light!', '2016-05-23 14:22:01.000000', NULL, 1),
(7456204, 1181502, 30982, '<td valign="top">That one leaf is the star of your show.</td>', 'That one leaf is the star of your show.', '2016-05-23 14:22:17.000000', NULL, 1),
(7456205, 1181343, 30982, '<td valign="top">Good shallow DOF and control of the exposure.</td>', 'Good shallow DOF and control of the exposure.', '2016-05-23 14:23:12.000000', NULL, 1),
(7456206, 1181679, 30982, '<td valign="top">Nice choice to go with B&amp;W.</td>', 'Nice choice to go with B&W.', '2016-05-23 14:23:26.000000', NULL, 1),
(7456207, 1181682, 30982, '<td valign="top">Excellent contrast!  I really like this sort of texture/shape exploration and this is very well done.</td>', 'Excellent contrast!  I really like this sort of texture/shape exploration and this is very well done.', '2016-05-23 14:23:58.000000', NULL, 1),
(7456216, 1181632, 30982, '<td valign="top">Good job with exposure for minimal editing.</td>', 'Good job with exposure for minimal editing.', '2016-05-23 15:24:51.000000', NULL, 1),
(7456217, 1181550, 30982, '<td valign="top">Would make a nice card!</td>', 'Would make a nice card!', '2016-05-23 15:25:24.000000', NULL, 1),
(7456218, 1181593, 30982, '<td valign="top">I like how they''re not entirely symmetrical.</td>', 'I like how they''re not entirely symmetrical.', '2016-05-23 15:26:15.000000', NULL, 1),
(7456219, 1181659, 30982, '<td valign="top">Very nice the way it''s difficult to resolve what we''re seeing - has a nice gentle flow to it, and I love the wee bit of sun in the upper corner.</td>', 'Very nice the way it''s difficult to resolve what we''re seeing - has a nice gentle flow to it, and I love the wee bit of sun in the upper corner.', '2016-05-23 15:26:58.000000', NULL, 1),
(7456220, 1181685, 30982, '<td valign="top">A bit unsettling in that the lower half doesn''t resolve for me.  That''s not a bad thing, just an observation.  It sort of creates an interesting tension.</td>', 'A bit unsettling in that the lower half doesn''t resolve for me.  That''s not a bad thing, just an observation.  It sort of creates an interesting tension.', '2016-05-23 15:29:53.000000', NULL, 1),
(7456221, 1181676, 30982, '<td valign="top">A nice composition but one of those that would benefit from a bit of editing were this not minimal - that wee bit in the lower right corner could go, and the sky could be brightened a touch.  I like the conversation, though.</td>', 'A nice composition but one of those that would benefit from a bit of editing were this not minimal - that wee bit in the lower right corner could go, and the sky could be brightened a touch.  I like the conversation, though.', '2016-05-23 15:30:58.000000', NULL, 1),
(7456222, 1181613, 30982, '<td valign="top">Cool!  We''re in the home movie, somewhere trapped in time.</td>', 'Cool!  We''re in the home movie, somewhere trapped in time.', '2016-05-23 15:31:19.000000', NULL, 1),
(7456223, 1181330, 30982, '<td valign="top">With minimal it''s tough to get horizons straight unless you use all that fancy equipment (tripod, level).  The overall picture is nice to remind you of a place visited, but may not be as significant to others.</td>', 'With minimal it''s tough to get horizons straight unless you use all that fancy equipment (tripod, level).  The overall picture is nice to remind you of a place visited, but may not be as significant to others.', '2016-05-23 15:33:11.000000', NULL, 1),
(7456225, 1181698, 30982, '<td valign="top">Pretty darn good job of squaring this up in camera.  A bit on the dull-ish side - undoubtedly could be helped with a bit of editing were it not minimal.  But an interesting tableau!</td>', 'Pretty darn good job of squaring this up in camera.  A bit on the dull-ish side - undoubtedly could be helped with a bit of editing were it not minimal.  But an interesting tableau!', '2016-05-23 15:35:20.000000', NULL, 1),
(7456227, 1181464, 30982, '<td valign="top">Heh!  I''ll just go with "OK!"  I probably don''t get it, though.  Not your fault - I''m old and slow.</td>', 'Heh!  I''ll just go with "OK!"  I probably don''t get it, though.  Not your fault - I''m old and slow.', '2016-05-23 15:36:22.000000', NULL, 1),
(7456228, 1181422, 30982, '<td valign="top">LOL!  Well, it''s good you entered.  Will say that the blur here doesn''t do anything for me, though.  Some times I like blur, sometimes I don''t.</td>', 'LOL!  Well, it''s good you entered.  Will say that the blur here doesn''t do anything for me, though.  Some times I like blur, sometimes I don''t.', '2016-05-23 15:37:23.000000', NULL, 1),
